head.script:
// [FAIL] gridView Body Column 의 disabledClass / readOnlyClass 는
//        "메소드를 사용하여 상태를 변경한 경우엔 적용되지 않습니다" 로 규정되어 있으나,
//        setColumnDisabled / setCellDisabled / setColumnReadOnly / setCellReadOnly 로
//        상태를 변경해도 해당 클래스가 그대로 적용된다.
//        col1 = 초기 렌더링 시 상태 지정 (적용되는 것이 정상)
//        col2 = 초기 렌더링 시 미지정 -> 메소드로 상태 변경 (적용되지 않아야 함)

scwin.onpageload = function () {
    scwin.printClass();
};



// 대상 Cell 에서 상태 관련 클래스만 추출 (엔진 기본 클래스 제외)
scwin.pickClass = function (gridId, colIndex, prefix, defaultClass) {
    let td = document.querySelector("td[id*='" + gridId + "_cell_0_" + colIndex + "']");
    if (!td) {
        return "(Cell 없음)";
    }
    let arr = td.className.split(/\s+/).filter(function (c) {
        return c === defaultClass || c.indexOf(prefix) === 0;
    });
    return arr.length ? arr.join(" ") : "없음";
};



// 현재 클래스 상태 출력
scwin.printClass = function () {
    scwin.setReturnValue("[disabled] col1 (초기 렌더 지정) : " + scwin.pickClass("grid_dis", 0, "dc_", "w2grid_default_disabled"));
    scwin.setReturnValue("[disabled] col2 (메소드 변경)     : " + scwin.pickClass("grid_dis", 1, "dc_", "w2grid_default_disabled"));
    scwin.setReturnValue("[readOnly] col1 (초기 렌더 지정) : " + scwin.pickClass("grid_ro", 0, "rc_", "w2grid_default_readonly"));
    scwin.setReturnValue("[readOnly] col2 (메소드 변경)     : " + scwin.pickClass("grid_ro", 1, "rc_", "w2grid_default_readonly"));
};



// 메소드로 col2 의 상태를 변경 (Column 단위 / Cell 단위)
scwin.btn_changeByMethod_onclick = function (e) {
    grid_dis.setColumnDisabled("col2", true);
    grid_dis.setCellDisabled(1, "col2", true);

    grid_ro.setColumnReadOnly("col2", true);
    grid_ro.setCellReadOnly(1, "col2", true);

    scwin.btn_clear_onclick();
    scwin.printClass();
};



// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
